import typing


class modint:
    def __init__(self,__x: int = 0,_raw: bool = False) -> None:
        if not _raw:
            self._x = (__x % MOD + MOD) % MOD
        else:
            self._x = __x

    def __str__(self):
        return str(self._x)

    __repr__ = __str__

    def __pos__(self) -> 'modint':
        return self

    def __neg__(self) -> 'modint':
        return modint(MOD - self._x,True)

    def __add__(self,other: typing.Union[int,'modint']) -> 'modint':
        if isinstance(other,modint):
            res = self._x + other._x
            if res >= MOD:
                res -= MOD
            return modint(res,True)
        else:
            return modint((self._x + other) % MOD,True)

    def __sub__(self,other: typing.Union[int,'modint']) -> 'modint':
        if isinstance(other,modint):
            res = self._x - other._x
            if res < 0:
                res += MOD
            return modint(res,True)
        else:
            return modint(self._x - other)

    def __mul__(self,other: typing.Union[int,'modint']) -> 'modint':
        return modint((self._x * other._x) if isinstance(other,modint) else (self._x * other))

    def inv(self) -> 'modint':
        a,b,u,v = self._x,MOD,1,0
        while b > 0:
            t = a // b
            a -= t * b;a,b = b,a
            u -= t * v;u,v = v,u
        return u

    def __truediv__(self,other: typing.Union[int,'modint']) -> 'modint':
        return modint((self._x * other.inv()) if isinstance(other,modint) else (self._x * modint(other).inv()))

    def __pow__(self,other: int) -> 'modint':
        return modint(pow(self._x,other,MOD),True)

    __radd__ = __add__

    def __rsub__(self,other: typing.Union[int,'modint']) -> 'modint':
        if isinstance(other,modint):
            res = other._x - self._x
            if res < 0:
                res += MOD
            return modint(res,True)
        else:
            return modint(other - self._x)

    __rmul__ = __mul__

    def __rtruediv__(self,other: typing.Union[int,'modint']) -> 'modint':
        return modint((other._x * self.inv()) if isinstance(other,modint) else (modint(other,True) * self.inv()))

def raw(x: int) -> 'modint':
    return modint(x,True)

