class Solver:
    def input(self):
        """
        faster input function than builtin stdin.
        """
        return sys.stdin.readline()[:-1]

    def ii(self, t: type = int):
        """
        input single value.
        """
        return t(self.input())

    def il(self, t: type = int):
        """
        input single line.
        """
        return list(map(t, self.input().split()))

    def imi(self, N: int, t: type = int):
        """
        input multi value.
        """
        return [self.ii(t) for _ in range(N)]

    def iml(self, N: int, t: type = int):
        """
        input multi line.
        """
        return [self.il(t) for _ in range(N)]

    def solve(self):
        A = self.ii()
        B = self.ii()
        if A>B:
            return "GREATER"
        if A<B:
            return "LESS"
        return "EQUAL"


