def modint(mod: int = 10**9 + 7, clsname: str = 'ModInt') -> 'type[int]':
    from functools import update_wrapper

    cls = type(clsname, (int,), {'__slots__': (), 'MOD': mod})
    new = int.__new__; _pow = pow
    @staticmethod
    def __new__(cls, x=0):
        return new(cls, x % mod)
    def __add__(self, other):
        return new(cls, (+self + (+other)) % mod)
    def __sub__(self, other):
        return new(cls, (+self - (+other)) % mod)
    def __mul__(self, other):
        return new(cls, (+self * (+other)) % mod)
    def __floordiv__(self, other):
        return new(cls, +self * _pow(+other, mod-2, mod) % mod)
    def __pow__(self, other, mod: int = mod):
        return new(cls, _pow(+self, +other, mod))
    def __lshift__(self, other):
        return new(cls, (+self << +other) % mod)
    def __radd__(self, other):
        return new(cls, (+other + (+self)) % mod)
    def __rsub__(self, other):
        return new(cls, (+other - (+self)) % mod)
    def __rmul__(self, other):
        return new(cls, (+other * (+self)) % mod)
    def __rfloordiv__(self, other):
        return new(cls, +other * _pow(+self, mod-2, mod) % mod)
    def __rpow__(self, other, mod: int = mod):
        return new(cls, _pow(+other, +self, mod))

    attrs = ('__module__', '__doc__',)
    for k, v in locals().items():
        if k.startswith('__'):
            setattr(cls, k, update_wrapper(v, getattr(cls, k), attrs, ()))
            v.__qualname__ = clsname + '.' + k

    return cls


