import sys

from collections import deque

class Graph:
    def __init__(self):
        self.edges = {}

    def append_edge(self, sv, ev, weight = 1):
        if sv in self.edges:
            self.edges[sv].append((ev, weight))
        else:
            self.edges[sv] = [(ev, weight)]

    def bfs(self, sv, N):
        dist = [-1]*N
        q = deque([])   # キュー
        q.append(sv)
        dist[sv] = 0
        connect_vtxs = []
        cnt = [0] * N
        cnt[0] = 1
        while len(q) > 0:
            p = q.popleft()     # キュー取りだし（先頭）
            connect_vtxs.append(p)
            if p not in self.edges:
                continue
            for (ev, w) in self.edges[p]:
                if dist[ev] == -1 or dist[ev] == dist[p] + 1:
                    cnt[ev] += cnt[p]
                if dist[ev] != -1:
                    continue
                q.append(ev)    # キュー追加
                dist[ev] = dist[p] + 1
        return dist, connect_vtxs, cnt

def main(f):
    N = int(f.readline())
    A = []
    for i in range(N):
        A.append(int(input()) - 1)
    g = Graph()
    for i in range(len(A)):
        g.append_edge(i, A[i])

    dist, connect_vtxs, cnt = g.bfs(0, N)
    return dist[1]

