          heappush(queue, (rate[i], k, i))
        heappush(infants[k], (-rate[i], i))

      def transfer(i, k):
        now = where[i]
        while infants[now]:
          r, j = heappop(infants[now])
          if where[j] != now or j == i: continue
          if highest_rate[now] != -r:
